    }
  },
  "signal_basis": {
    "component_id": "C019.signal_basis",
    "value": "Publication near a previously stated roster date is a candidate postponement signal, considered alongside preparation reports to identify a recurrent, independently corroborated, product-addressable retention point.",
    "scope": "Timing alone does not identify the cause. The stated verification prerequisites are assumed satisfied; intervention selection remains subject to the smallest-change constraint.",
