      "rationale": "The cited spans supply the candidate roster-timing signal, preparation questions, intervention-selection prerequisites and requirement for corroboration beyond behavioral retention."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C019.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
